mapper.update:
update cms_forum_post
set status = #{status}, audit_reason = #{auditReason}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select  from cms_forum_post

    is_deleted = 0
     and status = #{status} 
     and user_id = #{userId} 
     and title like concat('%', #{title}, '%') 

order by create_time desc
